// build.gradle.kts

// CONFIGURATION PHASE — runs on every build, including `./gradlew help`
val sha = ProcessBuilder("git", "rev-parse", "--short", "HEAD")
    .start().inputStream.bufferedReader().readText().trim()
println("Building $sha")   // so does this

// Eager: the configuration block runs even when the task is never requested
tasks.create("printShaEager") {
    doLast { println(sha) }
}

// ---------- the same thing, deferred ----------

// Lazy and tracked: the process starts only when something reads the value,
// and the configuration cache re-checks it instead of freezing it in.
val shaProvider: Provider<String> = providers.exec {
    commandLine("git", "rev-parse", "--short", "HEAD")
}.standardOutput.asText.map(String::trim)

// Lazy: this block runs only when `printSha` is in the task graph
tasks.register("printSha") {
    val sha = shaProvider              // capture the Provider, not `project`
    doLast { println(sha.get()) }      // EXECUTION PHASE — only when the task runs
}

