@CacheableTask
abstract class GenerateConfig : DefaultTask() {

    @get:Input
    abstract val apiUrl: Property<String>

    @get:InputFile
    @get:PathSensitive(PathSensitivity.RELATIVE)   // relative paths, so another checkout can hit
    abstract val template: RegularFileProperty

    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    @TaskAction
    fun generate() {
        val target = outputDir.file("Config.kt").get().asFile   // no `project` in here
        target.writeText(template.get().asFile.readText().replace("{URL}", apiUrl.get()))
    }
}

