// core/cart/api — interfaces and models; no Retrofit, no Room, no Android framework
interface CartRepository {
    val items: Flow<List<CartItem>>
    suspend fun add(sku: String)
}

data class CartItem(val sku: String, val qty: Int)

// core/cart/impl — the only module that knows how any of it is fetched or stored
internal class DefaultCartRepository @Inject constructor(
    private val service: CartService,
    private val dao: CartDao,
) : CartRepository {
    override val items = dao.observeAll().map { it.map(CartEntity::toItem) }
    override suspend fun add(sku: String) = dao.upsert(service.add(sku).toEntity())
}

@Module
@InstallIn(SingletonComponent::class)
internal abstract class CartModule {
    @Binds abstract fun bind(impl: DefaultCartRepository): CartRepository
}

