// Base code cannot import ScanActivity, so: install, then resolve by name
class ScanLauncher(private val manager: SplitInstallManager) {

    fun open(activity: Activity) {
        if ("scan" in manager.installedModules) return start(activity)

        manager.registerListener { state ->
            when (state.status()) {
                SplitInstallSessionStatus.REQUIRES_USER_CONFIRMATION ->
                    manager.startConfirmationDialogForResult(state, activity, RC_SPLIT)
                SplitInstallSessionStatus.INSTALLED -> start(activity)
                SplitInstallSessionStatus.FAILED -> showRetry(state.errorCode())
                else -> Unit
            }
        }
        manager.startInstall(SplitInstallRequest.newBuilder().addModule("scan").build())
    }

    private fun start(activity: Activity) {
        SplitCompat.installActivity(activity)      // without this the module's resources are missing
        activity.startActivity(Intent(activity, Class.forName("com.example.scan.ScanActivity")))
    }
}

